#import "TFAIAttachmentMenu.h"
#import "TFAIUIHelpers.h"
@interface TFAIAttachmentMenuPage : UIViewController
@property NSDictionary *contexts;
@property(copy) void(^selection)(NSString *);
@end
@implementation TFAIAttachmentMenuPage
- (UIButton *)source:(NSString *)title icon:(NSString *)icon key:(NSString *)key {
 BOOL row=[@[@"project",@"classdump",@"build_log",@"diagnostics"] containsObject:key];
 UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem];UIButtonConfiguration *config=[UIButtonConfiguration plainButtonConfiguration];config.title=title;config.image=[UIImage systemImageNamed:icon];config.imagePlacement=row?NSDirectionalRectEdgeLeading:NSDirectionalRectEdgeTop;config.imagePadding=row?14:9;config.baseForegroundColor=UIColor.labelColor;config.contentInsets=NSDirectionalEdgeInsetsMake(12,14,12,14);config.titleTextAttributesTransformer=^NSDictionary *(NSDictionary *a){NSMutableDictionary *v=[a mutableCopy];v[NSFontAttributeName]=[UIFont systemFontOfSize:14 weight:UIFontWeightMedium];return v;};
 if(row){config.subtitle=[key isEqual:@"classdump"]?@"保存本机附件，发送后让 AI 导出头文件":[key isEqual:@"project"]?@"选择文件，或进入文件夹后点 ✅ 授权目录":@"当前项目的本机编译记录";config.subtitleTextAttributesTransformer=^NSDictionary *(NSDictionary *a){NSMutableDictionary *v=[a mutableCopy];v[NSFontAttributeName]=[UIFont systemFontOfSize:11];v[NSForegroundColorAttributeName]=UIColor.secondaryLabelColor;return v;};button.contentHorizontalAlignment=UIControlContentHorizontalAlignmentLeading;}else{button.backgroundColor=UIColor.secondarySystemBackgroundColor;button.layer.cornerRadius=16;}
 button.configuration=config;button.accessibilityIdentifier=[@"attachment-source-" stringByAppendingString:key];button.accessibilityLabel=title;[button addAction:[UIAction actionWithHandler:^(UIAction *a){void(^select)(NSString *)=self.selection;[self dismissViewControllerAnimated:YES completion:^{if(select)select(key);}];}] forControlEvents:UIControlEventTouchUpInside];[button.heightAnchor constraintEqualToConstant:row?62:78].active=YES;return button;
}
- (void)viewDidLoad {
 [super viewDidLoad];self.title=@"添加附件";self.view.backgroundColor=UIColor.systemBackgroundColor;self.navigationItem.rightBarButtonItem=AIBar(@"xmark",@"关闭",self,@selector(close));
 UIStackView *media=[[UIStackView alloc]initWithArrangedSubviews:@[[self source:@"照片" icon:@"photo" key:@"photo"],[self source:@"相机" icon:@"camera" key:@"camera"],[self source:@"文件" icon:@"doc" key:@"file"]]];media.distribution=UIStackViewDistributionFillEqually;media.spacing=8;
 UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[media,[self source:@"项目文件与文件夹" icon:@"folder" key:@"project"]]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=10;[stack addArrangedSubview:[self source:@"IPA 头文件" icon:@"doc.text.magnifyingglass" key:@"classdump"]];
 NSMutableArray *sources=[NSMutableArray new];if([self.contexts[@"build_log"] boolValue])[sources addObject:[self source:@"构建日志" icon:@"text.alignleft" key:@"build_log"]];if([self.contexts[@"diagnostics"] boolValue])[sources addObject:[self source:@"构建诊断" icon:@"exclamationmark.bubble" key:@"diagnostics"]];if(sources.count){UIStackView *logs=[[UIStackView alloc]initWithArrangedSubviews:sources];logs.distribution=UIStackViewDistributionFillEqually;logs.spacing=8;[stack addArrangedSubview:logs];}
 UILabel *hint=[UILabel new];hint.text=@"图片在发送时提交给模型；文件只发送清单；文件夹只授予目录读取权限，不逐个添加或上传。模型按需读取的内容才会发给服务商。";hint.numberOfLines=0;hint.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption1];hint.textColor=UIColor.secondaryLabelColor;[stack addArrangedSubview:hint];UIScrollView *scroll=[UIScrollView new];scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:stack];[NSLayoutConstraint activateConstraints:@[[scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor],[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:12],[stack.leadingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.leadingAnchor constant:16],[stack.trailingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.trailingAnchor constant:-16],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-20],[stack.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor constant:-32]]];
}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
@end
UIViewController *TFAIAttachmentMenu(NSDictionary *contexts,void(^selection)(NSString *)){TFAIAttachmentMenuPage *page=[TFAIAttachmentMenuPage new];page.contexts=contexts?:@{};page.selection=selection;return page;}
